package controller;

import constants.Constants;
import constants.Message;
import dto.BookRequestDTO;
import dto.BookResponseDTO;
import java.util.ArrayList;
import java.util.List;
import repository.BookRepository;
import service.BookService;
import view.BookView;

/**
 * Dieu phoi moi yeu cau ve sach: goi Repository de them/tim/sua (CRUD), dua du lieu
 * cho Service sap xep, roi dua ket qua cho View in. Khong import model.
 *
 * @author CuongThai Academy
 */
public class BookController {

    // Kho sach (CRUD nam o Controller, khong o Service)
    private BookRepository bookRepository;

    // Nghiep vu sap xep
    private BookService bookService;

    // Man hinh in ket qua
    private BookView bookView;

    // Tao kho, service, view va nap sach mau
    public BookController() {
        bookRepository = new BookRepository();
        bookService = new BookService();
        bookView = new BookView();

        // Nap sach mau; loi thi in ra (khong xay ra voi du lieu mau dung)
        try {
            loadSampleBooks();
        } catch (Exception e) {
            // Du lieu mau trung ISBN thi bao loi
            showResult(e.getMessage(), new ArrayList<BookResponseDTO>());
        }
    }

    // Them 1 sach, bao ket qua (thanh cong kem ma moi, hoac trung ISBN)
    public void addBook(BookRequestDTO bookRequestDTO) {
        // Cau ket qua se in
        String resultMessage = "";

        // Them vao kho (kho cap ma); trung ISBN thi kho nem loi
        try {
            resultMessage = String.format(Message.SUCCESS_ADD,
                    bookRepository.addBook(bookRequestDTO), bookRequestDTO.getTitle(),
                    bookRepository.countBooks());
        } catch (Exception e) {
            // Trung ISBN thi lay cau bao loi cua kho
            resultMessage = e.getMessage();
        }

        // In ket qua 1 lan
        showResult(resultMessage, new ArrayList<BookResponseDTO>());
    }

    // Sua so ban cua 1 sach (phieu dien ma + so ban moi), bao so cu -> so moi
    public void updateCopies(BookRequestDTO bookRequestDTO) {
        // Cau ket qua se in
        String resultMessage = "";

        // Lay ban sao TRUOC khi sua (giu so cu), roi sua trong kho
        try {
            BookResponseDTO before = bookRepository.findById(bookRequestDTO.getId());

            // Sua trong kho; ban sao "before" KHONG doi theo vi no la doi tuong khac
            bookRepository.updateCopies(bookRequestDTO);
            resultMessage = String.format(Message.SUCCESS_UPDATE_COPIES, before.getId(),
                    before.getTitle(), before.getCopies(), bookRequestDTO.getCopies());
        } catch (Exception e) {
            // Khong co ma sach thi lay cau bao loi cua kho
            resultMessage = e.getMessage();
        }

        // In ket qua 1 lan
        showResult(resultMessage, new ArrayList<BookResponseDTO>());
    }

    // In moi sach, sap theo ten
    public void showAllBooks() {
        // Kho tra ban sao, Service sap xep + danh so
        List<BookResponseDTO> sortedList = bookService.sortByTitle(bookRepository.findAll());

        // Kho rong thi chi in cau bao rong, nguoc lai chi in bang
        if (sortedList.isEmpty()) {
            showResult(Message.EMPTY_LIST, sortedList);
        } else {
            // Co sach thi in bang, khong kem cau nao
            showResult("", sortedList);
        }
    }

    // Tim sach co ten chua tu khoa (phieu chi dien ten), in ket qua da sap theo ten
    public void searchBooks(BookRequestDTO bookRequestDTO) {
        // Kho tim theo tu khoa, Service sap xep + danh so
        List<BookResponseDTO> foundList
                = bookService.sortByTitle(bookRepository.findByKeyword(bookRequestDTO.getTitle()));

        // Khong tim thay thi chi in cau bao, nguoc lai chi in bang
        if (foundList.isEmpty()) {
            showResult(String.format(Message.NOT_FOUND, bookRequestDTO.getTitle()), foundList);
        } else {
            // Co ket qua thi in bang
            showResult("", foundList);
        }
    }

    // Dua cau thong bao + cac dong bang cho View roi goi in dung 1 lan
    private void showResult(String message, List<BookResponseDTO> responseList) {
        bookView.setMessage(message);
        bookView.setResponseList(responseList);
        bookView.display();
    }

    // Nap cac sach mau khai trong Constants
    private void loadSampleBooks() throws Exception {
        // Moi dong mau: { ten sach, ISBN, tac gia, nam, so ban }
        for (String[] rowArray : Constants.SAMPLE_BOOK_ARRAY) {
            bookRepository.addBook(toRequestDTO(rowArray));
        }
    }

    // Doi 1 dong mau (mang chuoi) thanh phieu sach
    private BookRequestDTO toRequestDTO(String[] rowArray) {
        // Phieu sach moi
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Chep tung cot cua dong mau vao phieu
        bookRequestDTO.setTitle(rowArray[Constants.SAMPLE_TITLE_INDEX]);
        bookRequestDTO.setIsbn(rowArray[Constants.SAMPLE_ISBN_INDEX]);
        bookRequestDTO.setAuthor(rowArray[Constants.SAMPLE_AUTHOR_INDEX]);
        bookRequestDTO.setYear(Integer.parseInt(rowArray[Constants.SAMPLE_YEAR_INDEX]));
        bookRequestDTO.setCopies(Integer.parseInt(rowArray[Constants.SAMPLE_COPIES_INDEX]));
        return bookRequestDTO;
    }
}

package controller;

import constants.Constants;
import constants.Message;
import dto.MemberRequestDTO;
import dto.MemberResponseDTO;
import java.util.ArrayList;
import java.util.List;
import repository.MemberRepository;
import service.MemberService;
import view.MemberView;

/**
 * Dieu phoi moi yeu cau ve thanh vien: goi Repository de them/lay (CRUD),
 * dua du lieu cho Service sap xep, roi dua ket qua cho View in. Khong import model.
 *
 * @author CuongThai Academy
 */
public class MemberController {

    // Kho thanh vien (CRUD)
    private MemberRepository memberRepository;

    // Nghiep vu sap xep thanh vien
    private MemberService memberService;

    // Man hinh in ket qua
    private MemberView memberView;

    // Tao kho, service, view va nap thanh vien mau
    public MemberController() {
        memberRepository = new MemberRepository();
        memberService = new MemberService();
        memberView = new MemberView();

        // Moi dong mau: { ho ten, email }
        for (String[] rowArray : Constants.SAMPLE_MEMBER_ARRAY) {
            memberRepository.addMember(toRequestDTO(rowArray));
        }
    }

    // Them 1 thanh vien, bao ma vua cap
    public void addMember(MemberRequestDTO memberRequestDTO) {
        // Kho cap ma va them; cau bao kem ma va tong so thanh vien
        String resultMessage = String.format(Message.SUCCESS_ADD_MEMBER,
                memberRepository.addMember(memberRequestDTO), memberRequestDTO.getName(),
                memberRepository.countMembers());

        // In ket qua 1 lan
        showResult(resultMessage, new ArrayList<MemberResponseDTO>());
    }

    // In moi thanh vien, sap theo ho ten
    public void showAllMembers() {
        // Kho tra ban sao, Service sap xep + danh so
        List<MemberResponseDTO> sortedList
                = memberService.sortByName(memberRepository.findAll());

        // Rong thi chi in cau bao rong, nguoc lai chi in bang
        if (sortedList.isEmpty()) {
            showResult(Message.EMPTY_MEMBER_LIST, sortedList);
        } else {
            // Co thanh vien thi in bang
            showResult("", sortedList);
        }
    }

    // Dua cau thong bao + cac dong bang cho View roi goi in dung 1 lan
    private void showResult(String message, List<MemberResponseDTO> responseList) {
        memberView.setMessage(message);
        memberView.setResponseList(responseList);
        memberView.display();
    }

    // Doi 1 dong mau (mang chuoi) thanh phieu thanh vien
    private MemberRequestDTO toRequestDTO(String[] rowArray) {
        // Phieu thanh vien moi
        MemberRequestDTO memberRequestDTO = new MemberRequestDTO();

        // Chep ho ten va email cua dong mau vao phieu
        memberRequestDTO.setName(rowArray[Constants.SAMPLE_NAME_INDEX]);
        memberRequestDTO.setEmail(rowArray[Constants.SAMPLE_EMAIL_INDEX]);
        return memberRequestDTO;
    }
}

package dto;

/**
 * Phieu du lieu Main gui sang Controller (moi o da kiem hop le o utils).
 * Them sach: dien du; cap nhat so ban: chi dien id + copies; tim sach: chi dien title.
 *
 * @author CuongThai Academy
 */
public class BookRequestDTO {

    // Ma sach (khi cap nhat)
    private String id;

    // ISBN-13 da kiem
    private String isbn;

    // Ten sach da chuan hoa (hoac tu khoa khi tim)
    private String title;

    // Tac gia da chuan hoa
    private String author;

    // Nam xuat ban
    private int year;

    // So ban
    private int copies;

    // Constructor rong (JavaBean)
    public BookRequestDTO() {
    }

    // Tra ve ma sach
    public String getId() {
        return id;
    }

    // Gan ma sach
    public void setId(String id) {
        this.id = id;
    }

    // Tra ve ISBN
    public String getIsbn() {
        return isbn;
    }

    // Gan ISBN
    public void setIsbn(String isbn) {
        this.isbn = isbn;
    }

    // Tra ve ten sach
    public String getTitle() {
        return title;
    }

    // Gan ten sach
    public void setTitle(String title) {
        this.title = title;
    }

    // Tra ve tac gia
    public String getAuthor() {
        return author;
    }

    // Gan tac gia
    public void setAuthor(String author) {
        this.author = author;
    }

    // Tra ve nam xuat ban
    public int getYear() {
        return year;
    }

    // Gan nam xuat ban
    public void setYear(int year) {
        this.year = year;
    }

    // Tra ve so ban
    public int getCopies() {
        return copies;
    }

    // Gan so ban
    public void setCopies(int copies) {
        this.copies = copies;
    }
}

package dto;

import constants.Constants;

